import express from "express";

type Room = {
  id: number;
  name: string;
  building: string;
  capacity: number;
  amenities: string[];
};

const rooms = new Map<number, Room>([
  [1, { id: 1, name: "Turing", building: "main-library", capacity: 6, amenities: ["whiteboard", "screen"] }],
  [2, { id: 2, name: "Lovelace", building: "main-library", capacity: 4, amenities: ["whiteboard"] }],
  [3, { id: 3, name: "Hopper", building: "science-library", capacity: 8, amenities: ["screen", "video-call"] }],
]);

const app = express();

app.get("/v1/rooms/:roomId", (req, res) => {
  const room = rooms.get(Number(req.params.roomId));
  if (room === undefined) {
    res.status(404).json({ title: "Room not found" });
    return;
  }
  res.json(room);
});

app.listen(4000, "127.0.0.1", (error) => {
  if (error) {
    throw error;
  }
  console.log("Roombook is listening on http://localhost:4000");
});
